let __v_3894 = Value::from("Check the entry requirements on the university or college page for the exact course, because they differ more than people expect - most want five GCSEs at grade 4 or above including English and maths, and A-levels or a BTEC in a subject that fits. Pick the subjects that keep two doors open rather than one, and ask a teacher or someone doing the job now what they actually needed.");
frame.store("THE_GENERAL_CAREER", __v_3894.clone())?;
let __v_3895 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"nurse\",\"nursing\"]},\"Three years for a nursing degree, two for a nursing associate course, or four on a degree apprenticeship where you are paid while you train.\",\"A return-to-practice course, not the degree again: about 450 hours of supervised practice and a short theory module, which most trusts run over three to six months, and they tell you which one they take at the interview.\"]},{\"$tuple\":[{\"$tuple\":[\"midwife\",\"midwifery\"]},\"Three years for a midwifery degree, or four years on a midwifery apprenticeship, which pays while you train.\",\"A return-to-practice course of a few months supervised in a maternity unit, rather than the degree again, if you have let your registration lapse.\"]},{\"$tuple\":[{\"$tuple\":[\"dentist\",\"dentistry\",\"dental school\",\"dental surgeon\"]},\"Five years at dental school, then a year of dental foundation training in a practice before you can work on your own, so six years from starting to being paid as a dentist.\",\"A return-to-practice or the overseas registration exam rather than the degree again: around a year of study and supervised practice, and the General Dental Council says which route your qualification needs.\"]},{\"$tuple\":[{\"$tuple\":[\"doctor\",\"medicine\",\"medical school\",\"surgeon\"]},\"Five years at medical school, then two foundation years in a hospital before you can apply for specialty training, which runs from three to eight years depending on the field.\",\"If you qualified as a doctor abroad, the route is the PLAB exams and then a couple of years in a training post, not a second degree.\"]},{\"$tuple\":[{\"$tuple\":[\"teacher\",\"teaching\",\"primary school teacher\",\"secondary school teacher\"]},\"Three years for a degree and then one more for a PGCE or a school-based training year, so four in all, or about the same on a teaching apprenticeship, which pays.\",\"A refresher course of a few weeks rather than a second degree, if you taught before and let the registration go.\"]},{\"$tuple\":[{\"$tuple\":[\"vet\",\"veterinary\",\"vet school\"]},\"Five years at vet school, and there is no shorter route into it.\",\"\"]},{\"$tuple\":[{\"$tuple\":[\"lawyer\",\"law\",\"solicitor\",\"barrister\",\"law degree\"]},\"Three years for a law degree, then two years of qualifying work experience while you sit the SQE exams - so four to five years in all, or a year more if you do a conversion course instead of the law degree.\",\"A conversion course of a year, then the same two years of qualifying work experience.\"]},{\"$tuple\":[{\"$tuple\":[\"engineer\",\"engineering\",\"mechanical engineer\",\"civil engineer\",\"electrical engineer\"]},\"Four years for an MEng, or three for a BEng and then a few years of supervised work to chartership.\",\"A degree apprenticeship of four to six years, paid throughout, which is the usual way back in if you already work in the industry.\"]},{\"$tuple\":[{\"$tuple\":[\"accountant\",\"accountancy\",\"accounting\",\"chartered accountant\"]},\"Three to four years of exams, AAT first and then ACCA or ACA, taken while you work, so you are paid from the first year.\",\"The same three to four years of exams, starting at the level you left off at, and a firm will usually take you on as a trainee while you sit them.\"]},{\"$tuple\":[{\"$tuple\":[\"paramedic\",\"paramedic science\"]},\"Three years for a paramedic science degree, or about two years as an associate ambulance practitioner inside a trust, which pays.\",\"\"]},{\"$tuple\":[{\"$tuple\":[\"pharmacist\",\"pharmacy\"]},\"Four years for an MPharm, then a year of foundation training in a pharmacy before you register.\",\"A refresher placement and the registration assessment rather than the degree again.\"]},{\"$tuple\":[{\"$tuple\":[\"physiotherapist\",\"physiotherapy\"]},\"Three years for a physiotherapy degree, or two on an accelerated Masters if you already have a degree in a science.\",\"A return-to-practice course of a few weeks, run by the Chartered Society of Physiotherapy, if you have been out of the register.\"]},{\"$tuple\":[{\"$tuple\":[\"architect\",\"architecture\"]},\"Three years for a degree, then two years of practical experience and the Part 3 exam - seven years in all, and the Part 3 is the part people underestimate.\",\"The Part 2 and Part 3 years, on top of the experience you already have, rather than the whole degree again.\"]},{\"$tuple\":[{\"$tuple\":[\"social worker\",\"social work\"]},\"Three years for a social work degree, or two on a Masters if your first degree is in something related, and there are fast-track programmes that pay a salary while you train.\",\"A return-to-practice course of a few weeks, and the register tells you what you need.\"]},{\"$tuple\":[{\"$tuple\":[\"police\",\"police officer\"]},\"No degree is needed: you apply to a force and train on the job, or take the three-year police constable degree apprenticeship, which is paid throughout.\",\"You go back in at your previous rank where the force allows it, with a short refresher rather than the full training again.\"]},{\"$tuple\":[{\"$tuple\":[\"electrician\",\"plumber\",\"plumbing\",\"gas engineer\"]},\"Three to four years for a level 3 apprenticeship, which is how nearly everyone gets in, and the gas or electrics registration adds a year or two after that.\",\"A level 2 refresher and the registration assessment rather than the whole apprenticeship.\"]},{\"$tuple\":[{\"$tuple\":[\"chef\"]},\"Two to three years as a commis chef through an apprenticeship or a college course, and you are paid from the first week.\",\"A short refresher in a kitchen and the level 2 assessment rather than the whole thing again.\"]},{\"$tuple\":[{\"$tuple\":[\"mechanic\",\"carpenter\",\"bricklayer\",\"joiner\"]},\"Three to four years for a level 3 apprenticeship, which is how nearly everyone gets in.\",\"A short refresher and the level 2 assessment rather than the whole apprenticeship.\"]}]}")?;
